use vstd::prelude::*;

verus! {
    /// Given a vector of row‐indices `indices` and a
    /// matrix `choices`, pick from each column `i` the
    /// entry in row `indices[i]`.
    fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> (result: Vec<f64>)
        /// For each position i in `indices` we must have
        ///   1) the row‐index is in bounds of `choices`
        ///   2) the column i is in bounds of that chosen row
        requires
            forall |i: usize| i < indices.len() ==>
                (indices[i] as usize) < choices.len(),
            forall |i: usize| i < indices.len() ==>
                i < choices[(indices[i] as usize)].len(),
        /// We return a vector of exactly the same length,
        /// and at each position we picked the specified element.
        ensures
            result.len() == indices.len(),
            forall |i: usize| i < result.len() ==>
                result[i] == choices[(indices[i] as usize)][i],
    {
        let n = indices.len();
        let mut result = Vec::with_capacity(n);
        // Desugar `for i in 0..n` so we can give an invariant.
        let mut i: usize = 0;
        while i < n
            invariant
                // We never overshoot
                i <= n,
                // We've already pushed exactly `i` elements
                result.len() == i,
                // And those first `i` elements are correct
                forall |j: usize| j < i ==>
                    result[j] == choices[(indices[j] as usize)][j],
            decreases n - i,
        {
            let row = indices[i] as usize;
            // These two asserts help the verifier—though they should
            // already follow from our requires clauses.
            assert(row < choices.len());
            assert(i < choices[row].len());
            result.push(choices[row][i]);
            i += 1;
        }
        result
    }
} // end verus!

